// test_features.mjs -- verifies public/js/features.js's sdfAndHeight()
// against two references (fixtures/feature_vectors.json, generated by
// gen_reference.py):
//   1. expected_web_grid: the SAME downsampled arrays quantized into
//      public/data/sdf_*.bin / height_grid.bin -- JS must match this to
//      within int16 quantization (scale 0.01 m per axis, worst-case
//      trilinear-combined error bounded by ~4*scale/2 = 0.02 m for the SDF
//      corners plus a similar bilinear bound for height).
//   2. reference_full_res_grid: the ORIGINAL, full-resolution training grid
//      (not downsampled) -- reported only, to quantify how much accuracy
//      the web's <10 MB budget costs relative to training (not a pass/fail
//      gate; see web/README.md "Precision de la geometria en el navegador").
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { sdfAndHeight } from "../public/js/features.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const DATA = join(__dirname, "../public/data");

function loadGrids() {
  const sdfMeta = JSON.parse(readFileSync(join(DATA, "sdf_grid_meta.json"), "utf-8"));
  const heightMeta = JSON.parse(readFileSync(join(DATA, "height_grid_meta.json"), "utf-8"));
  const toI16 = (buf) => new Int16Array(buf.buffer, buf.byteOffset, buf.byteLength / 2);
  const fine = { ...sdfMeta.fine, data: toI16(readFileSync(join(DATA, sdfMeta.fine.file))), scale: sdfMeta.quantization.scale };
  const coarse = { ...sdfMeta.coarse, data: toI16(readFileSync(join(DATA, sdfMeta.coarse.file))), scale: sdfMeta.quantization.scale };
  const height = { ...heightMeta, data: toI16(readFileSync(join(DATA, heightMeta.file))), scale: heightMeta.quantization.scale };
  return { fine, coarse, height };
}

function main() {
  const grids = loadGrids();
  const fixtures = JSON.parse(readFileSync(join(__dirname, "fixtures/feature_vectors.json"), "utf-8"));
  const quantScale = fixtures.quant_scale;
  // Quantization bound: each of the up to 8 corners used by trilinear
  // interpolation can be off by scale/2 from rounding; interpolation
  // weights sum to 1, so the combined error is bounded by scale/2, with a
  // generous safety factor for floating-point roundoff.
  const TOL_SDF = quantScale / 2 + 1e-6;
  const TOL_HEIGHT = quantScale / 2 + 1e-6;

  let maxSdfDiff = 0, maxHeightDiff = 0;
  let sumFullResSdfDiff = 0, maxFullResSdfDiff = 0;

  for (const c of fixtures.cases) {
    const { sdf, height } = sdfAndHeight(grids, c.x, c.y, c.z);
    const dSdf = Math.abs(sdf - c.expected_web_grid.sdf);
    const dHeight = Math.abs(height - c.expected_web_grid.height);
    maxSdfDiff = Math.max(maxSdfDiff, dSdf);
    maxHeightDiff = Math.max(maxHeightDiff, dHeight);

    const dFull = Math.abs(sdf - c.reference_full_res_grid.sdf);
    sumFullResSdfDiff += dFull;
    maxFullResSdfDiff = Math.max(maxFullResSdfDiff, dFull);
  }

  console.log(`[test_features] ${fixtures.n} puntos`);
  console.log(`  SDF vs grid re-muestreado (lo que JS DEBE reproducir): max|diff| = ${maxSdfDiff.toFixed(5)} m (tolerancia ${TOL_SDF.toFixed(5)} m)`);
  console.log(`  altura vs grid re-muestreado: max|diff| = ${maxHeightDiff.toFixed(5)} m (tolerancia ${TOL_HEIGHT.toFixed(5)} m)`);
  console.log(`  [informativo] SDF vs grid ORIGINAL de entrenamiento (1m/4m): media|diff| = ${(sumFullResSdfDiff / fixtures.n).toFixed(3)} m, max|diff| = ${maxFullResSdfDiff.toFixed(3)} m`);

  if (maxSdfDiff >= TOL_SDF || maxHeightDiff >= TOL_HEIGHT) {
    console.error("FALLO: la interpolacion JS no reproduce el grid descargado dentro de la cuantizacion esperada.");
    process.exit(1);
  }
  console.log("OK: la interpolacion JS reproduce el grid descargado (sdf_fine/coarse.bin, height_grid.bin) dentro del error de cuantizacion.");
}

main();
